nextflow_process {

    name "Test Process BINETTE"
    script "../main.nf"
    process "BINETTE"

    tag "modules"
    tag "modules_nfcore"
    tag "binette"

    config './nextflow.config'

    test("bacteroides_fragilis - genome") {

        setup {
            new File("${launchDir}/c2b_1.txt").text = """
            NZ_CP069563.1\tbin1
            NZ_CP069564.1\tbin2
            """.stripIndent().trim()

            new File("${launchDir}/c2b_2.txt").text = """
            NZ_CP069563.1\tbin1
            NZ_CP069564.1\tbin2
            """.stripIndent().trim()
        }

        when {

            params {
                binette_args = "--low_mem"
            }

            process {
                """
                input[0] = [
                    [ id:'test' ],
                    [file("${launchDir}/c2b_1.txt"), file("${launchDir}/c2b_2.txt")],
                    [],
                    file(params.modules_testdata_base_path + "genomics/prokaryotes/bacteroides_fragilis/genome/genome.fna.gz"),
                    []
                ]
                input[1] = [[id: "db"], file(params.modules_testdata_base_path + "delete_me/binette_checkm2/binette_checkm2_small_db.dmnd")]
                """
            }
        }

        then {
            assert process.success
            assertAll(
                { assert snapshot(sanitizeOutput(process.out)).match() }
            )
        }

    }

    test("bacteroides_fragilis - stub") {

        options "-stub"

        setup {
            new File("${launchDir}/c2b_1.txt").text = """
            NZ_CP069563.1\tbin1
            NZ_CP069564.1\tbin2
            """.stripIndent().trim()

            new File("${launchDir}/c2b_2.txt").text = """
            NZ_CP069563.1\tbin1
            NZ_CP069564.1\tbin2
            """.stripIndent().trim()
        }

        when {

            params {
                binette_args = "--low_mem"
            }

            process {
                """
                input[0] = [
                    [ id:'test' ],
                    [file("${launchDir}/c2b_1.txt"), file("${launchDir}/c2b_2.txt")],
                    [],
                    file(params.modules_testdata_base_path + "genomics/prokaryotes/bacteroides_fragilis/genome/genome.fna.gz"),
                    []
                ]
                input[1] = [[id: "db"], file(params.modules_testdata_base_path + "delete_me/binette_checkm2/binette_checkm2_small_db.dmnd")]
                """
            }
        }

        then {
            assert process.success
            assertAll(
                { assert snapshot(sanitizeOutput(process.out)).match() }
            )
        }

    }

}
